11: // Merge two copies of a concept's obs list as a multiset union: for each
12: // (obsDatetime, value) identity, keep the highest count seen in either list.
13: // The obstree backend serializes a concept's full obs list once per branch, so
14: // equal obs within one list are genuinely distinct results, while equal lists
15: // across branches are copies of the same results. obsDatetime + value is the
16: // best identity available until the backend exposes obs uuids; it cannot
17: // distinguish a copy from a real duplicate that only ever appears in separate
18: // lists, which is a documented limitation rather than a bug to fix here.
19: export function mergeObsMultisetMax(
20:   existing: Array<ObservationData>,
21:   incoming: Array<ObservationData>,
22: ): Array<ObservationData> {
23:   const merged = [...existing];
24:   const existingCounts = new Map<string, number>();
25:   for (const obs of existing) {
26:     const id = `${obs.obsDatetime}|${obs.value}`;
27:     existingCounts.set(id, (existingCounts.get(id) ?? 0) + 1);
28:   }
29:   const incomingCounts = new Map<string, number>();
30:   for (const obs of incoming) {
31:     const id = `${obs.obsDatetime}|${obs.value}`;
32:     const seen = (incomingCounts.get(id) ?? 0) + 1;
33:     incomingCounts.set(id, seen);
34:     if (seen > (existingCounts.get(id) ?? 0)) {
35:       merged.push(obs);
36:     }
37:   }
38:   return merged;
39: }
